# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DİVAN ŞİİRİNDE GAZEL VE KASİDE NAZIM BİÇİMLERİ (TDE2.3)</text>\n  <rect x="20" y="42" width="322" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="181" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">GAZEL (AŞK, GÜZELLİK VE LİRİZM)</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• Nazım birimi: Beyit (5 - 15 beyit) | Ölçü: Aruz</text>\n  <text x="32" y="108" font-size="10.8" fill="#1e3a8a">• Kafiye şeması: aa / ba / ca / da / ea...</text>\n  <text x="32" y="128" font-size="10.8" font-weight="bold" fill="#1e3a8a">• Matla: İlk beyit (aa) | Makta: Son beyit</text>\n  <text x="32" y="148" font-size="10.8" fill="#1e3a8a">• Beytü\'l-gazel (Şah beyit): En güzel beyit</text>\n  <text x="32" y="168" font-size="10.8" fill="#1e3a8a">• Taç beyit: Şairin mahlasının geçtiği son beyit</text>\n  <text x="32" y="188" font-size="10.5" fill="#1e3a8a">• Konularına göre: Âşıkane (Fuzûlî), Rindane (Bâkî),</text>\n  <text x="40" y="203" font-size="10.5" fill="#1e3a8a">Şûhane (Nedîm), Hikemî (Nâbî).</text>\n  <rect x="358" y="42" width="322" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="519" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">KASİDE (ÖVGÜ VE YERGİ ŞİİRİ)</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• Nazım birimi: Beyit (33 - 99 beyit) | Ölçü: Aruz</text>\n  <text x="370" y="108" font-size="10.8" fill="#14532d">• Kafiye şeması: aa / ba / ca / da... (Gazelle aynı)</text>\n  <text x="370" y="128" font-size="10.8" font-weight="bold" fill="#14532d">• Kasidenin 6 Bölümü: 1. Nesib (Teşbib),</text>\n  <text x="378" y="144" font-size="10.5" fill="#14532d">2. Girizgâh, 3. Methiye, 4. Tegazzül, 5. Fahriye, 6. Dua</text>\n  <text x="370" y="166" font-size="10.8" font-weight="bold" fill="#14532d">• Konularına Göre Kasideler:</text>\n  <text x="378" y="182" font-size="10.5" fill="#14532d">Tevhid, Münacat, Naat (Su Kasidesi), Methiye,</text>\n  <text x="378" y="198" font-size="10.5" fill="#14532d">Hicviye (Sihâm-ı Kazâ - Nef\'î), Mersiye.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bütün beyitleri aynı konuyu işleyen gazele "yek-ahenk", aynı söyleyiş gücünde olana "yek-avaz" gazel denir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HALK ŞİİRİNDE KOŞMA İLE DİVAN ŞİİRİNDE GAZELİN KARŞILAŞTIRILMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">ÂŞIK TARZI HALK ŞİİRİ: KOŞMA</text>\n  <text x="35" y="88" font-size="10.8" fill="#78350f">• Nazım birimi: Dörtlük (3 - 5 dörtlük)</text>\n  <text x="35" y="108" font-size="10.8" fill="#78350f">• Ölçü: 11\'li hece ölçüsü (6+5 veya 4+4+3 duraklı)</text>\n  <text x="35" y="128" font-size="10.8" fill="#78350f">• Kafiye şeması: abab (xaxa) / cccb / dddb</text>\n  <text x="35" y="148" font-size="10.8" fill="#78350f">• Son dörtlükte şair mahlasını söyler (Tapşırma).</text>\n  <text x="35" y="168" font-size="10.8" font-weight="bold" fill="#78350f">• Konularına Göre Türleri (4 Tür):</text>\n  <text x="45" y="184" font-size="10.5" fill="#78350f">Güzelleme (Karacaoğlan), Koçaklama (Köroğlu),</text>\n  <text x="45" y="200" font-size="10.5" fill="#78350f">Taşlama (Seyranî) ve Ağıt.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">KOŞMA VE GAZEL ORTAK / FARKLI YÖNLER</text>\n  <text x="370" y="88" font-size="10.8" font-weight="bold" fill="#581c87">• Ortak Yönleri (Tema ve Lirizm):</text>\n  <text x="380" y="104" font-size="10.5" fill="#581c87">Her ikisi de aşk, ayrılık, doğa ve özlem temalarını</text>\n  <text x="380" y="120" font-size="10.5" fill="#581c87">işleyen lirik şiirlerdir; son birimde mahlas yer alır.</text>\n  <text x="370" y="144" font-size="10.8" font-weight="bold" fill="#581c87">• Farklı Yönleri (Yapı, Dil ve Gelenek):</text>\n  <text x="380" y="160" font-size="10.5" fill="#581c87">Koşma: Dörtlük + Hece + Yalın Türkçe + Somut güzellik</text>\n  <text x="380" y="176" font-size="10.5" fill="#581c87">Gazel: Beyit + Aruz + Süslü dil + Soyut mazmunlar</text>\n  <text x="380" y="192" font-size="10.5" fill="#581c87">(gül-bülbül, servi boy, ok kirpik, keman kaş).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Divan şiirindeki Hicviye ⟷ Halk şiirindeki Taşlama | Divan şiirindeki Mersiye ⟷ Halk şiirindeki Ağıt.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ŞİİRDE AHENK UNSURLARI VE EDEBÎ SANATLAR (SÖZ SANATLARI)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">AHENK UNSURLARI (RİTİM VE SES)</text>\n  <text x="35" y="88" font-size="10.8" fill="#064e3b">• Ölçü (Vezin): Hece (sayı/durak) ve Aruz (açık/kapalı)</text>\n  <text x="35" y="110" font-size="10.8" fill="#064e3b">• Redif: Dize sonunda aynı görevli ek/kelime tekrarı</text>\n  <text x="35" y="132" font-size="10.8" fill="#064e3b">• Kafiye (Uyak): Yarım (1 ses), Tam (2 ses),</text>\n  <text x="45" y="148" font-size="10.5" fill="#064e3b">Zengin (3+ ses), Tunç ve Cinaslı kafiye</text>\n  <text x="35" y="170" font-size="10.8" fill="#064e3b">• Aliterasyon (ünsüz tekrarı) &amp; Asonans (ünlü tekrarı)</text>\n  <text x="35" y="192" font-size="10.8" fill="#064e3b">• İç kafiye (musammat) ve nakarat tekrarı</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">BAŞLICA SÖZ SANATLARI (EDEBÎ SANATLAR)</text>\n  <text x="370" y="88" font-size="10.8" fill="#881337">• Teşbih (Benzetme) &amp; İstiare (Açık / Kapalı Eğretileme)</text>\n  <text x="370" y="110" font-size="10.8" fill="#881337">• Teşhis (Kişileştirme) &amp; İntak (Konuşturma)</text>\n  <text x="370" y="132" font-size="10.8" fill="#881337">• Tenasüp (Anlamca ilgili kelimeleri bir arada kullanma)</text>\n  <text x="370" y="154" font-size="10.8" fill="#881337">• Tezat (Karşıt kavramları bir arada kullanma)</text>\n  <text x="370" y="176" font-size="10.8" fill="#881337">• Telmih (Tarihî/dinî olaya gönderme) &amp; Hüsnütalil</text>\n  <text x="370" y="198" font-size="10.8" fill="#881337">• Mübalağa (Abartma) &amp; Tecahülüarif (Bilmezden gelme)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kural: Dize sonunda önce REDİF (aynı görevli ek/kelime), onun solundaki kök/gövdede KAFİYE aranır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
